def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def searchNodesVisited(tree, target):
    if not tree:
        return 0
    val, left, right = parse(tree)
    u = 0
    steps = 0
    while u != -1:
        steps += 1
        if val[u] == target:
            break
        u = left[u] if target < val[u] else right[u]
    return steps
